parameters.functionCode:
const content = $node["OpenAI - Intake Classifier"].json?.message?.content || '';
try {
  const parsed = JSON.parse(content);
  return [{ json: { valid: true, parsed } }];
} catch (e) {
  return [{ json: { valid: false, error: e.message, raw: content } }];
}

