parameters.query:
={{
`
UPDATE clients
SET
    total_messages = total_messages + 1,
    updated_at = NOW(),
    last_message_at = NOW(),
    current_keyword = '${$node["Validate - Intake JSON"].json.parsed.keyword}',
    current_stage = '${$node["Validate - Qualification JSON"].json.parsed.next_stage}',
    emotional_state = '${$node["Validate - Emotional JSON"].json.parsed.emotional_state}',
    emotional_intensity = ${$node["Validate - Emotional JSON"].json.parsed.emotional_intensity},
    interaction_type = '${$node["Validate - Intake JSON"].json.parsed.interaction_type}',
    consultation_interest = ${
      $node["Validate - Qualification JSON"].json.parsed.offer_eligibility_signal !== "not_yet"
    }
WHERE telegram_user_id = ${$node["Telegram Trigger"].json["message"]["from"]["id"]}
RETURNING *;
`
}}
